def masterplan():
    return f'''<section class="section masterplan" id="masterplan"><div class="wrap"><div class="section-heading">{eyebrow('THE MASTERPLAN')}<h2>A neighbourhood,<br>considered <em>as one.</em></h2></div><div class="plan-image-wrap plan-video-wrap"><video class="plan-video" muted loop playsinline preload="none" poster="assets/img/master-layout-832.webp" width="832" height="464" aria-label="Aerial walkthrough of the Valencia Town masterplan"><source data-src="assets/video/walkthrough.mp4" type="video/mp4"></video></div><div class="plan-caption"><span>A CONNECTED COMMUNITY</span><button class="plan-expand" data-open-plan>Explore full plan <span aria-hidden="true">↗</span></button><span>Indicative layout · Artist’s impression</span></div><div class="plan-discovery"><figure class="plan-figure"><img id="plan-image" src="assets/img/{P['masterplan'][0]['image']}-640.webp" srcset="assets/img/{P['masterplan'][0]['image']}-640.webp 640w, assets/img/{P['masterplan'][0]['image']}-1280.webp 1280w" sizes="(max-width: 767px) 100vw, 42vw" width="640" height="360" alt="" loading="lazy" decoding="async"><figcaption>Artist’s impression</figcaption></figure><div class="plan-detail" id="plan-detail" aria-live="polite"><p class="eyebrow">01 / 08</p><h3>Grand entrance</h3><p>{P['masterplan'][0]['description']}</p></div><div class="discovery-controls"><button data-plan-prev aria-label="Explore previous place">←</button><button data-plan-next aria-label="Explore next place">→</button></div></div><div class="plan-links"><button class="text-link" data-open-plan>View full masterplan <span aria-hidden="true">↗</span></button>{cta('Request layout','Layout','button-dark')}</div></div></section>'''
