def plots():
    return f'''<section class="plots section wrap" id="plots"><div class="reveal">{eyebrow('YOUR PLACE WITHIN VALENCIA')}<h2>Space to build<br><em>life your way.</em></h2></div><div class="plot-details reveal"><span class="plot-line-art" aria-hidden="true"><i></i><i></i><i></i></span><p class="eyebrow">RESIDENTIAL PLOTS</p><p class="plot-size">{P['plotSizes']}<small>square feet</small></p><p class="plot-price">Starting from ₹{todo(P['priceFrom'],'—')} lakh · {e(P['paymentPlan'])}</p><p class="fine">Approximate sizes. Availability changes.<br>Pricing on request.</p>{cta('Enquire about plots','Plot Availability','button-dark')}</div></section>'''
def location():
    return f'''<section class="location section" id="location"><div class="wrap location-grid"><div class="location-copy">{eyebrow('A PLACE IN BETWEEN')}<h2>Between<br>Indore <em>&amp; Ujjain.</em></h2><p class="editorial">Connected to the city.<br>Surrounded by space.</p><ul class="route-list">{''.join(f'<li><span>{"Sri Aurobindo Hospital (SAIMS)" if k=="SAIMS" else k}</span><span>{v} min</span></li>' for k,v in P['distances'].items())}</ul><p class="fine">Drive times are approximate and vary with traffic and route.</p><a class="text-link" href="https://www.google.com/maps/dir/?api=1&amp;destination={P['latitude']},{P['longitude']}" target="_blank" rel="noopener">Get directions <span aria-hidden="true">↗</span></a></div><div class="journey"><div class="map-embed" id="map-embed"><button class="map-load" data-load-map>{mark('map-mark')}<span>Load the map</span><small>Indore–Ujjain Road · SAIMS · Vijay Nagar · Airport · Ujjain</small></button></div><div class="route-axis" aria-label="Valencia Town at Shahna, between Indore and Ujjain"><span class="route-city">INDORE</span><div class="route-valencia"><strong>VALENCIA TOWN</strong><small>SHAHNA · YOUR PLACE IN BETWEEN</small></div><span class="route-city">UJJAIN</span></div><p class="fine">Schematic route, not to scale.</p></div></div></section>'''
