def visit():
    return f'''<section class="visit forest" id="visit">{image('entrance-road','Tree-lined entrance road into Valencia Town at dusk','visit-image')}<div class="visit-shade"></div><div class="wrap visit-content">{eyebrow('YOUR NEXT CHAPTER')}<h2>Come see<br><em>Valencia.</em></h2><p>Some places are better experienced<br>than explained.</p><div class="visit-actions">{cta(cls='button-light')}{cta('Request brochure','Brochure')}</div>{mark('visit-mark')}</div></section>'''
def faqs():
    d=P['distances']
    return [('Where is Valencia Town located?','Valencia Town is at Shahna on the Indore–Ujjain Road in Madhya Pradesh, between Indore and Ujjain.'),('What plot sizes are offered?',f'Residential plots are approximately {P["plotSizes"]} sq ft. Current sizes and availability can be confirmed with the sales team.'),('What is planned within the community?','The planned amenities include a clubhouse, temple, children’s playground, forest-style gardens, sports courts, landscaped lawns, senior citizens’ library, meeting zone, women’s activity zone, wide internal roads and gated security. Specifications and layouts are indicative and subject to change.'),('How well connected is the location?',f'Sri Aurobindo Hospital (SAIMS) is approximately {d["SAIMS"]} minutes away, Vijay Nagar and Indore Airport approximately {d["Vijay Nagar"]} minutes, and Ujjain approximately {d["Ujjain"]} minutes. Times vary with traffic and route.'),('How can I arrange a private visit?','Use Arrange a Private Visit and leave your name and mobile number. The team can help with a visit, current plot availability or a brochure.'),('Where can I check approvals and project details?','Request the current project documentation and applicable approvals from the sales team before making a decision. The communicated project scale is '+P['investment'].lower()+'.')]
def faq():
    return f'''<section class="faq section wrap" id="faq"><div class="faq-intro">{eyebrow('A FEW THINGS TO KNOW')}<h2>Questions,<br><em>answered.</em></h2><p>The essentials, in brief. For anything else, the Valencia team is a conversation away.</p><button class="button-dark" data-enquiry="Site Visit" data-call>Speak to the team<span aria-hidden="true">↗</span></button></div><div class="faq-list">{''.join(f'<details><summary>{e(q)}<span aria-hidden="true">+</span></summary><div class="faq-answer"><p>{e(a)}</p></div></details>' for q,a in faqs())}</div></section><section class="seo wrap"><details><summary>Read more about the location <span aria-hidden="true">+</span></summary><div><h3>Residential plots on the Indore–Ujjain Road</h3><p>For families exploring residential plots near Indore or Ujjain, Valencia Town brings together planned community spaces and room to build a personal home. Its Shahna address on the Indore–Ujjain corridor connects the township with Sri Aurobindo Hospital (SAIMS), Vijay Nagar and the wider region.</p><p>When considering plots on Indore–Ujjain Road, explore the location in person, review current layout documentation and confirm available plot sizes. Our team can help you understand the planned amenities and arrange a private visit.</p></div></details></section>'''
def developer():
    D=P['developer']
    tes=[t for t in P['testimonials'] if not str(t['quote']).startswith('TODO')]
    tes_html=''
    if tes:
        items=[]
        for t in tes:
            items.append('<blockquote><p>“'+e(t['quote'])+'”</p><footer>'+e(t['name'])+'<span>'+e(t['detail'])+'</span></footer></blockquote>')
        tes_html='<div class="testimonials">'+''.join(items)+'</div>'
    prog=[x for x in P['progressPhotos'] if (ROOT/('assets/img/'+x.get('image','')+'-1280.webp')).exists()]
    prog_html=''
    if prog:
        items=[]
        for x in prog:
            items.append('<figure>'+image(x['image'],x['caption'],sizes='(max-width: 767px) 85vw, 32vw')+'<figcaption>'+e(x['caption'])+' · '+e(x['date'])+'</figcaption></figure>')
        prog_html='<div class="progress-grid">'+''.join(items)+'</div>'
    past=', '.join(todo(x) for x in D['pastProjects']); banks=', '.join(todo(x) for x in D['bankTieUps'])
    return f'''<section class="developer section wrap" id="developer"><div class="developer-intro">{eyebrow('THE DEVELOPER')}<h2>Built by people<br>who <em>stay.</em></h2><p>{todo(D['name'])}, part of {todo(D['group'])}. Developing in the region since {todo(D['since'])}.</p></div><dl class="facts"><div><dt>Past projects</dt><dd>{past}</dd></div><div><dt>Construction status</dt><dd>{todo(D['constructionStatus'])}</dd></div><div><dt>Possession</dt><dd>{todo(D['possession'])}</dd></div><div><dt>Bank tie-ups</dt><dd>{banks}</dd></div><div><dt>Sales gallery</dt><dd>{todo(D['salesGallery'])}<br>{e(D['hours'])}</dd></div><div><dt>Speak to us</dt><dd><a href="{phone_href()}">{e(P['SALES_PHONE'])}</a><br><a href="mailto:{e(P['SALES_EMAIL'])}">{e(P['SALES_EMAIL'])}</a></dd></div></dl>{tes_html}{prog_html}</section>'''
